import java.util.*;

class Solution {
    public long fib(int n) {
        long[] memo = new long[n + 1];
        Arrays.fill(memo, -1);
        return fibMemo(n, memo);
    }

    private long fibMemo(int n, long[] memo) {
        if (n <= 1) return n;
        if (memo[n] != -1) return memo[n];
        memo[n] = fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
        return memo[n];
    }
}

