class Solution {
    public int sumArray(int[] nums) {
        return sumFrom(nums, 0);
    }

    private int sumFrom(int[] nums, int i) {
        if (i == nums.length) return 0;
        return nums[i] + sumFrom(nums, i + 1);
    }
}

